  "inlineSchema": "// ============================================================\n// CCNA Simulator - Database Schema\n// Provider: SQLite (migrable to PostgreSQL)\n// ============================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ---- Users ----\n\nmodel User {\n  id           String   @id @default(cuid())\n  email        String   @unique\n  username     String   @unique\n  passwordHash String\n  role         String   @default(\"user\") // user | admin\n  language     String   @default(\"en\") // en | es\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  exams     Exam[]\n  favorites QuestionFavorite[]\n}\n\n// ---- Topics (Exam Areas & Sub-topics) ----\n\nmodel Topic {\n  id                 String  @id @default(cuid())\n  code               String  @unique // e.g. \"1.0\", \"1.1\", \"1.1.a\"\n  nameEn             String\n  nameEs             String\n  descriptionEn      String?\n  descriptionEs      String?\n  examArea           String // network_fundamentals, network_access, etc.\n  examAreaNumber     String // \"1.0\", \"2.0\", etc.\n  weightPercentage   Int // 20, 20, 25, 10, 15, 10\n  examVersion        String  @default(\"200-301-v1.1\")\n  learningObjectives String? // JSON array stored as text\n\n  parentTopicId String?\n  parentTopic   Topic?  @relation(\"TopicHierarchy\", fields: [parentTopicId], references: [id])\n  childTopics   Topic[] @relation(\"TopicHierarchy\")\n\n  questions Question[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ---- Sources ----\n\nmodel Source {\n  id              String    @id @default(cuid())\n  name            String\n  url             String?\n  sourceType      String // official_docs, original, user_import, rfc, textbook\n  consultedAt     DateTime?\n  reuseConditions String?\n  license         String?\n  validationNotes String?\n\n  questions Question[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ---- Questions ----\n\nmodel Question {\n  id               String  @id @default(cuid())\n  questionFamilyId String? // Groups original + variants together\n\n  // Bilingual statements\n  statementEn String\n  statementEs String\n\n  // Classification\n  questionType        String // single_choice, multiple_choice, true_false, subnetting, etc.\n  difficulty          String // basic, intermediate, advanced\n  multipleAnswerCount Int? // For multiple_choice: how many answers to select\n\n  // Timing\n  estimatedTimeSeconds Int @default(90)\n\n  // Validation\n  validationStatus String    @default(\"draft\") // draft, pending_review, validated, rejected\n  lastVerifiedAt   DateTime?\n  examVersion      String    @default(\"200-301-v1.1\")\n\n  // Bilingual explanations\n  explanationEn              String?\n  explanationEs              String?\n  correctAnswerExplanationEn String?\n  correctAnswerExplanationEs String?\n\n  // Topic relation\n  primaryTopicId String\n  primaryTopic   Topic   @relation(fields: [primaryTopicId], references: [id])\n  subtopics      String? // JSON array of topic IDs\n\n  // Source relation\n  sourceId      String?\n  source        Source? @relation(fields: [sourceId], references: [id])\n  sourceUrl     String?\n  sourceLicense String?\n\n  // Relations\n  options            QuestionOption[]\n  variantsAsOriginal QuestionVariant[]  @relation(\"OriginalQuestion\")\n  variantsAsVariant  QuestionVariant[]  @relation(\"VariantQuestion\")\n  examQuestions      ExamQuestion[]\n  favorites          QuestionFavorite[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ---- Question Options ----\n\nmodel QuestionOption {\n  id         String   @id @default(cuid())\n  questionId String\n  question   Question @relation(fields: [questionId], references: [id], onDelete: Cascade)\n\n  optionLabel   String // \"A\", \"B\", \"C\", \"D\", \"E\", \"F\"\n  optionTextEn  String\n  optionTextEs  String\n  isCorrect     Boolean @default(false)\n  explanationEn String?\n  explanationEs String?\n  displayOrder  Int\n\n  examResponses ExamResponse[]\n}\n\n// ---- Question Variants ----\n\nmodel QuestionVariant {\n  id                 String    @id @default(cuid())\n  originalQuestionId String\n  originalQuestion   Question  @relation(\"OriginalQuestion\", fields: [originalQuestionId], references: [id])\n  variantQuestionId  String\n  variantQuestion    Question  @relation(\"VariantQuestion\", fields: [variantQuestionId], references: [id])\n  modifiedParameters String? // JSON: what was changed\n  validationStatus   String    @default(\"draft\")\n  reviewedAt         DateTime?\n\n  createdAt DateTime @default(now())\n}\n\n// ---- Exams ----\n\nmodel Exam {\n  id     String  @id @default(cuid())\n  userId String?\n  user   User?   @relation(fields: [userId], references: [id])\n\n  // Configuration (stored for history)\n  questionCount   Int\n  durationMinutes Int\n  language        String // en | es\n  mode            String // full_simulation, topic_practice, custom, etc.\n  difficulty      String // basic, intermediate, advanced, mixed\n  strictMode      Boolean @default(true)\n  studyMode       Boolean @default(false)\n  selectedTopics  String? // JSON array of topic IDs\n  examVersion     String  @default(\"200-301-v1.1\")\n\n  // State\n  status             String    @default(\"configured\") // configured, in_progress, completed, expired, abandoned\n  currentQuestionIdx Int       @default(0)\n  startedAt          DateTime?\n  expiresAt          DateTime?\n  completedAt        DateTime?\n\n  // Results (calculated on completion)\n  score            Float?\n  percentage       Float?\n  correctCount     Int?\n  incorrectCount   Int?\n  unansweredCount  Int?\n  totalTimeSeconds Int?\n\n  // Exam questions\n  questions ExamQuestion[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ---- Exam Questions (selected questions for each exam) ----\n\nmodel ExamQuestion {\n  id            String   @id @default(cuid())\n  examId        String\n  exam          Exam     @relation(fields: [examId], references: [id], onDelete: Cascade)\n  questionId    String\n  question      Question @relation(fields: [questionId], references: [id])\n  questionOrder Int // Position in exam (0-indexed)\n\n  // Response tracking\n  status           String    @default(\"pending\") // pending, answered, skipped, timed_out\n  answeredAt       DateTime?\n  timeSpentSeconds Int?\n\n  responses ExamResponse[]\n\n  @@unique([examId, questionOrder])\n}\n\n// ---- Exam Responses (confirmed answers) ----\n\nmodel ExamResponse {\n  id               String         @id @default(cuid())\n  examQuestionId   String\n  examQuestion     ExamQuestion   @relation(fields: [examQuestionId], references: [id], onDelete: Cascade)\n  selectedOptionId String\n  selectedOption   QuestionOption @relation(fields: [selectedOptionId], references: [id])\n  isCorrect        Boolean? // Calculated on exam completion\n  confirmedAt      DateTime       @default(now())\n\n  @@unique([examQuestionId, selectedOptionId])\n}\n\n// ---- Question Favorites ----\n\nmodel QuestionFavorite {\n  id         String   @id @default(cuid())\n  userId     String\n  user       User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  questionId String\n  question   Question @relation(fields: [questionId], references: [id], onDelete: Cascade)\n  createdAt  DateTime @default(now())\n\n  @@unique([userId, questionId])\n}\n",
